//     The failing row and anything after it are not yielded.
//     Check Err() afterwards for the terminal cause.
//
//  4. Memory profile: O(rows × requested columns) buffered before
//     the first yield. Bounded by table size, not walk position —
//     callers that broke out early via 'for row := range Iter()'
//     still pay the full-walk buffer cost.
func (tw *IfTableWalker) Iter() iter.Seq2[snmp.OID, IfTableRow] {
	return func(yield func(snmp.OID, IfTableRow) bool) {
		entryWire := snmp.MustOID(1, 3, 6, 1, 2, 1, 2, 2, 1).WireBytes()
		buffer := make(map[string]*IfTableRow)
		var orderIdx []snmp.OID
		var orderKey []string

		for rv := range tw.rw.Iter() {
			if !bytes.HasPrefix(rv.OID, entryWire) {
				continue
			}
			suffix := rv.OID[len(entryWire):]
			colID, colLen, okArc := snmp.RawFirstArc(suffix)
			if !okArc || colLen >= len(suffix) {
				continue
			}
			idxWire := suffix[colLen:]
			row, exists := buffer[string(idxWire)]
			if !exists {
				idx, idxErr := snmp.DecodeIndexArcs(idxWire)
				if idxErr != nil {
					continue
				}
				key := string(idxWire)
				row = &IfTableRow{}
				buffer[key] = row
				orderIdx = append(orderIdx, idx)
				orderKey = append(orderKey, key)
			}
			_, ok := tw.byCol[colID]
			if !ok {
				continue
			}
			var derr error
			switch colID {
			case 1:
				if v, okRaw := snmp.RawInteger32(rv); okRaw {
					row.IfIndex = int32(v)
				} else {
					vb, vbErr := rv.Decode()
					if vbErr != nil {
						derr = vbErr
					} else {
						dv, dErr := IfIndex.Decode(vb)
						if dErr != nil {
							derr = dErr
						} else {
							row.IfIndex = dv
						}
					}
				}
			case 2:
				vb, vbErr := rv.Decode()
				if vbErr != nil {
					derr = vbErr
				} else {
					dv, dErr := IfDescr.Decode(vb)
					if dErr != nil {
						derr = dErr
					} else {
						row.IfDescr = dv
					}
				}
			case 3:
				if v, okRaw := snmp.RawInteger32(rv); okRaw {
					row.IfType = ianaiftype.IANAifType(v)
				} else {
					vb, vbErr := rv.Decode()
					if vbErr != nil {
						derr = vbErr
					} else {
						dv, dErr := IfType.Decode(vb)
						if dErr != nil {
							derr = dErr
						} else {
							row.IfType = dv
						}
					}
				}
			case 4:
				if v, okRaw := snmp.RawInteger32(rv); okRaw {
					row.IfMtu = int32(v)
				} else {
					vb, vbErr := rv.Decode()
					if vbErr != nil {
						derr = vbErr
					} else {
						dv, dErr := IfMtu.Decode(vb)
						if dErr != nil {
							derr = dErr
						} else {
							row.IfMtu = dv
						}
					}
				}
			case 5:
				if v, okRaw := snmp.RawGauge32(rv); okRaw {
					row.IfSpeed = uint32(v)
				} else {
					vb, vbErr := rv.Decode()
					if vbErr != nil {
						derr = vbErr
					} else {
						dv, dErr := IfSpeed.Decode(vb)
						if dErr != nil {
							derr = dErr
						} else {
							row.IfSpeed = dv
						}
					}
				}
			case 6:
				vb, vbErr := rv.Decode()
				if vbErr != nil {
					derr = vbErr
				} else {
					dv, dErr := IfPhysAddress.Decode(vb)
					if dErr != nil {
						derr = dErr
					} else {
						row.IfPhysAddress = dv
					}
				}
			case 7:
				if v, okRaw := snmp.RawInteger32(rv); okRaw {
					row.IfAdminStatus = IfAdminStatusValue(v)
				} else {
					vb, vbErr := rv.Decode()
					if vbErr != nil {
						derr = vbErr
					} else {
						dv, dErr := IfAdminStatus.Decode(vb)
						if dErr != nil {
							derr = dErr
						} else {
							row.IfAdminStatus = dv
						}
					}
				}
			case 8:
				if v, okRaw := snmp.RawInteger32(rv); okRaw {
					row.IfOperStatus = IfOperStatusValue(v)
				} else {
					vb, vbErr := rv.Decode()
					if vbErr != nil {
						derr = vbErr
					} else {
						dv, dErr := IfOperStatus.Decode(vb)
						if dErr != nil {
							derr = dErr
						} else {
							row.IfOperStatus = dv
						}
					}
				}
			case 9:
				if v, okRaw := snmp.RawTimeTicks(rv); okRaw {
					row.IfLastChange = uint32(v)
				} else {
					vb, vbErr := rv.Decode()
					if vbErr != nil {
						derr = vbErr
					} else {
						dv, dErr := IfLastChange.Decode(vb)
						if dErr != nil {
							derr = dErr
						} else {
							row.IfLastChange = dv
						}
					}
				}
			case 10:
				if v, okRaw := snmp.RawCounter32(rv); okRaw {
					row.IfInOctets = uint32(v)
				} else {
					vb, vbErr := rv.Decode()
					if vbErr != nil {
						derr = vbErr
					} else {
						dv, dErr := IfInOctets.Decode(vb)
						if dErr != nil {
							derr = dErr
						} else {
							row.IfInOctets = dv
						}
					}
				}
			case 11:
				if v, okRaw := snmp.RawCounter32(rv); okRaw {
					row.IfInUcastPkts = uint32(v)
				} else {
					vb, vbErr := rv.Decode()
					if vbErr != nil {
						derr = vbErr
					} else {
						dv, dErr := IfInUcastPkts.Decode(vb)
						if dErr != nil {
							derr = dErr
						} else {
							row.IfInUcastPkts = dv
						}
					}
				}
			case 12:
				if v, okRaw := snmp.RawCounter32(rv); okRaw {
					row.IfInNUcastPkts = uint32(v)
				} else {
					vb, vbErr := rv.Decode()
					if vbErr != nil {
						derr = vbErr
					} else {
						dv, dErr := IfInNUcastPkts.Decode(vb)
						if dErr != nil {
							derr = dErr
						} else {
							row.IfInNUcastPkts = dv
						}
					}
				}
			case 13:
				if v, okRaw := snmp.RawCounter32(rv); okRaw {
					row.IfInDiscards = uint32(v)
				} else {
					vb, vbErr := rv.Decode()
					if vbErr != nil {
						derr = vbErr
					} else {
						dv, dErr := IfInDiscards.Decode(vb)
						if dErr != nil {
							derr = dErr
						} else {
							row.IfInDiscards = dv
						}
					}
				}
			case 14:
				if v, okRaw := snmp.RawCounter32(rv); okRaw {
					row.IfInErrors = uint32(v)
				} else {
					vb, vbErr := rv.Decode()
					if vbErr != nil {
						derr = vbErr
					} else {
						dv, dErr := IfInErrors.Decode(vb)
						if dErr != nil {
							derr = dErr
						} else {
							row.IfInErrors = dv
						}
					}
				}
			case 15:
				if v, okRaw := snmp.RawCounter32(rv); okRaw {
					row.IfInUnknownProtos = uint32(v)
				} else {
					vb, vbErr := rv.Decode()
					if vbErr != nil {
						derr = vbErr
					} else {
						dv, dErr := IfInUnknownProtos.Decode(vb)
						if dErr != nil {
							derr = dErr
						} else {
							row.IfInUnknownProtos = dv
						}
					}
				}
			case 16:
				if v, okRaw := snmp.RawCounter32(rv); okRaw {
					row.IfOutOctets = uint32(v)
				} else {
					vb, vbErr := rv.Decode()
					if vbErr != nil {
						derr = vbErr
					} else {
						dv, dErr := IfOutOctets.Decode(vb)
						if dErr != nil {
							derr = dErr
						} else {
							row.IfOutOctets = dv
						}
					}
				}
			case 17:
				if v, okRaw := snmp.RawCounter32(rv); okRaw {
					row.IfOutUcastPkts = uint32(v)
				} else {
					vb, vbErr := rv.Decode()
					if vbErr != nil {
						derr = vbErr
					} else {
						dv, dErr := IfOutUcastPkts.Decode(vb)
						if dErr != nil {
							derr = dErr
						} else {
							row.IfOutUcastPkts = dv
						}
					}
				}
			case 18:
				if v, okRaw := snmp.RawCounter32(rv); okRaw {
					row.IfOutNUcastPkts = uint32(v)
				} else {
					vb, vbErr := rv.Decode()
					if vbErr != nil {
						derr = vbErr
					} else {
						dv, dErr := IfOutNUcastPkts.Decode(vb)
						if dErr != nil {
							derr = dErr
						} else {
							row.IfOutNUcastPkts = dv
						}
					}
				}
			case 19:
				if v, okRaw := snmp.RawCounter32(rv); okRaw {
					row.IfOutDiscards = uint32(v)
				} else {
					vb, vbErr := rv.Decode()
					if vbErr != nil {
						derr = vbErr
					} else {
						dv, dErr := IfOutDiscards.Decode(vb)
						if dErr != nil {
							derr = dErr
						} else {
							row.IfOutDiscards = dv
						}
					}
				}
			case 20:
				if v, okRaw := snmp.RawCounter32(rv); okRaw {
					row.IfOutErrors = uint32(v)
				} else {
					vb, vbErr := rv.Decode()
					if vbErr != nil {
						derr = vbErr
					} else {
						dv, dErr := IfOutErrors.Decode(vb)
						if dErr != nil {
							derr = dErr
						} else {
							row.IfOutErrors = dv
						}
					}
				}
			case 21:
				if v, okRaw := snmp.RawGauge32(rv); okRaw {
					row.IfOutQLen = uint32(v)
				} else {
					vb, vbErr := rv.Decode()
					if vbErr != nil {
						derr = vbErr
					} else {
						dv, dErr := IfOutQLen.Decode(vb)
						if dErr != nil {
							derr = dErr
						} else {
							row.IfOutQLen = dv
						}
					}
				}
			case 22:
				vb, vbErr := rv.Decode()
				if vbErr != nil {
					derr = vbErr
				} else {
					dv, dErr := IfSpecific.Decode(vb)
					if dErr != nil {
						derr = dErr
					} else {
						row.IfSpecific = dv
					}
				}
			}
			if derr != nil {
				for i := 0; i < len(orderKey); i++ {
					if orderKey[i] == string(idxWire) {
						break
					}
					if !yield(orderIdx[i], *buffer[orderKey[i]]) {
						tw.rw.Fail(derr)
						return
					}
				}
				tw.rw.Fail(derr)
				return
			}
		}

		for i := 0; i < len(orderIdx); i++ {
			if !yield(orderIdx[i], *buffer[orderKey[i]]) {
				return
			}
		}
	}
}

// Err returns the underlying walker's terminal error, or nil if
// the walk completed naturally.
func (tw *IfTableWalker) Err() error {
	return tw.rw.Err()
}

// ifTableT is the singleton type of IfTable.
type ifTableT struct{}

// IfTable is the descriptor for the ifTable table.
var IfTable ifTableT

// Walk launches a BulkWalk over ifTable and returns a
// table-aware iterator. Only the columns listed in cols are
// decoded; varbinds for unlisted columns are skipped. The walk
// rides the raw fast path (BulkWalkRaw); sessions or responses
// that cannot deliver raw bytes degrade transparently to the
// generic per-varbind decode.
func (ifTableT) Walk(ctx context.Context, sess snmp.Session, cols ...snmp.AnyColumn) *IfTableWalker {
	w := sess.BulkWalkRaw(ctx, snmp.MustOID(1, 3, 6, 1, 2, 1, 2, 2))
	byCol := make(map[uint32]snmp.AnyColumn, len(cols))

	for _, c := range cols {
		o := c.OID()
		if o.Len() == 0 {
			continue
		}
		byCol[o.At(o.Len()-1)] = c
	}

	return &IfTableWalker{
		byCol: byCol,
		cols:  cols,
		rw:    w,
	}
}

// decodeIfTableRow decodes one row of IfTable from the supplied
// VarBinds. Each VarBind's OID determines which row field it populates
// (via the column's last sub-id). VarBinds with unknown column-ids are
// ignored. Absent columns leave their field at its zero value.
func decodeIfTableRow(idx snmp.OID, vbs []snmp.VarBind) (IfTableRow, error) {
	var row IfTableRow
	row.Index = idx

	for _, vb := range vbs {
		o := vb.GetHeader().OID
		if o.Len() == 0 {
			continue
		}
		entryLen := snmp.MustOID(1, 3, 6, 1, 2, 1, 2, 2, 1).Len()
		if o.Len() <= entryLen {
			continue
		}
		colID := o.At(entryLen)
		switch colID {
		case 1:
			dv, derr := IfIndex.Decode(vb)
			if derr != nil {
				return row, derr
			}
			row.IfIndex = dv
		case 2:
			dv, derr := IfDescr.Decode(vb)
			if derr != nil {
				return row, derr
			}
			row.IfDescr = dv
		case 3:
			dv, derr := IfType.Decode(vb)
			if derr != nil {
				return row, derr
			}
			row.IfType = dv
		case 4:
			dv, derr := IfMtu.Decode(vb)
			if derr != nil {
				return row, derr
			}
			row.IfMtu = dv
		case 5:
			dv, derr := IfSpeed.Decode(vb)
			if derr != nil {
				return row, derr
			}
			row.IfSpeed = dv
		case 6:
			dv, derr := IfPhysAddress.Decode(vb)
			if derr != nil {
				return row, derr
			}
			row.IfPhysAddress = dv
		case 7:
			dv, derr := IfAdminStatus.Decode(vb)
			if derr != nil {
				return row, derr
			}
			row.IfAdminStatus = dv
		case 8:
			dv, derr := IfOperStatus.Decode(vb)
			if derr != nil {
				return row, derr
			}
			row.IfOperStatus = dv
		case 9:
			dv, derr := IfLastChange.Decode(vb)
			if derr != nil {
				return row, derr
			}
			row.IfLastChange = dv
		case 10:
			dv, derr := IfInOctets.Decode(vb)
			if derr != nil {
				return row, derr
			}
			row.IfInOctets = dv
		case 11:
			dv, derr := IfInUcastPkts.Decode(vb)
			if derr != nil {
				return row, derr
			}
			row.IfInUcastPkts = dv
		case 12:
			dv, derr := IfInNUcastPkts.Decode(vb)
			if derr != nil {
				return row, derr
			}
			row.IfInNUcastPkts = dv
		case 13:
			dv, derr := IfInDiscards.Decode(vb)
			if derr != nil {
				return row, derr
			}
			row.IfInDiscards = dv
		case 14:
			dv, derr := IfInErrors.Decode(vb)
			if derr != nil {
				return row, derr
			}
			row.IfInErrors = dv
		case 15:
			dv, derr := IfInUnknownProtos.Decode(vb)
			if derr != nil {
				return row, derr
			}
			row.IfInUnknownProtos = dv
		case 16:
			dv, derr := IfOutOctets.Decode(vb)
			if derr != nil {
				return row, derr
			}
			row.IfOutOctets = dv
		case 17:
			dv, derr := IfOutUcastPkts.Decode(vb)
			if derr != nil {
				return row, derr
			}
			row.IfOutUcastPkts = dv
		case 18:
			dv, derr := IfOutNUcastPkts.Decode(vb)
			if derr != nil {
				return row, derr
			}
			row.IfOutNUcastPkts = dv
		case 19:
			dv, derr := IfOutDiscards.Decode(vb)
			if derr != nil {
				return row, derr
			}
			row.IfOutDiscards = dv
		case 20:
			dv, derr := IfOutErrors.Decode(vb)
			if derr != nil {
				return row, derr
			}
			row.IfOutErrors = dv
		case 21:
			dv, derr := IfOutQLen.Decode(vb)
			if derr != nil {
				return row, derr
			}
			row.IfOutQLen = dv
		case 22:
			dv, derr := IfSpecific.Decode(vb)
			if derr != nil {
				return row, derr
			}
			row.IfSpecific = dv
		}
	}

	return row, nil
}

// equalIfTableRow compares two IfTableRow values for equality.
// Used by [snmp.Watcher] to compute ChangeKindModified emits. Field-by-
// field with the type-appropriate comparator (bytes.Equal for []byte,
// OID.Equal for OID, time.Time.Equal for time.Time, == for everything else).
func equalIfTableRow(a IfTableRow, b IfTableRow) bool {
	return a.Index.Equal(b.Index) && a.IfIndex == b.IfIndex && a.IfDescr == b.IfDescr && a.IfType == b.IfType && a.IfMtu == b.IfMtu && a.IfSpeed == b.IfSpeed && bytes.Equal(a.IfPhysAddress, b.IfPhysAddress) && a.IfAdminStatus == b.IfAdminStatus && a.IfOperStatus == b.IfOperStatus && a.IfLastChange == b.IfLastChange && a.IfInOctets == b.IfInOctets && a.IfInUcastPkts == b.IfInUcastPkts && a.IfInNUcastPkts == b.IfInNUcastPkts && a.IfInDiscards == b.IfInDiscards && a.IfInErrors == b.IfInErrors && a.IfInUnknownProtos == b.IfInUnknownProtos && a.IfOutOctets == b.IfOutOctets && a.IfOutUcastPkts == b.IfOutUcastPkts && a.IfOutNUcastPkts == b.IfOutNUcastPkts && a.IfOutDiscards == b.IfOutDiscards && a.IfOutErrors == b.IfOutErrors && a.IfOutQLen == b.IfOutQLen && a.IfSpecific.Equal(b.IfSpecific)
}

